/** Return all exercises for a given muscle group (by clickableSelections). */
export function getExercisesByMuscle(muscle: MuscleGroup): ExerciseDef[] {
  return EXERCISE_LIBRARY.filter(e => e.clickableSelections.includes(muscle));
}

/** Look up a single exercise by its stable exercise_id slug. */
export function getExerciseById(id: string): ExerciseDef | undefined {
  return EXERCISE_LIBRARY.find(e => e.exercise_id === id);
}

/** Look up a single exercise by display name (case-insensitive). */
export function getExerciseByName(name: string): ExerciseDef | undefined {
  const lower = name.toLowerCase();
  return EXERCISE_LIBRARY.find(e => e.name.toLowerCase() === lower);
}
